'use strict';
const $=id=>document.getElementById(id);
const sizes={'1:1':[1080,1080],'4:5':[1080,1350],'9:16':[1080,1920]};
const palettes={violet:['#29215e','#8874f0'],blue:['#083c64','#3aaac9'],peach:['#993c45','#ffa367']};
let state={ratio:'1:1',text:'오늘도 나답게,\n조금씩 앞으로.',size:76,color:'#ffffff',x:50,y:50,shadow:true,bg:'violet',image:null};
let picture=null,templates=[],selected=null,db=null,busy=false,uploadTicket=0;
const clone=x=>structuredClone(x);
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
function segments(text){return typeof Intl.Segmenter==='function'?[...new Intl.Segmenter('ko',{granularity:'grapheme'}).segment(text)].map(v=>v.segment):Array.from(text)}
function wrap(ctx,text,width){const lines=[];for(const paragraph of text.split(/\r\n?|\n/)){let line='';for(const c of segments(paragraph)){if(line&&ctx.measureText(line+c).width>width){lines.push(line);line=c}else line+=c}lines.push(line)}return lines}
function draw(canvas= $('canvas'),s=state,img=picture){const [w,h]=sizes[s.ratio];canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,w,h);if(img){const scale=Math.max(w/img.width,h/img.height);ctx.drawImage(img,(w-img.width*scale)/2,(h-img.height*scale)/2,img.width*scale,img.height*scale)}else{const [a,b]=palettes[s.bg],g=ctx.createLinearGradient(0,h,w,0);g.addColorStop(0,a);g.addColorStop(1,b);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#ffffff12';ctx.lineWidth=2;for(let n=0;n<6;n++){ctx.beginPath();ctx.arc(w*.85,h*.18,170+n*90,0,Math.PI*2);ctx.stroke()}}
ctx.font=`700 ${s.size}px Arial, "Malgun Gothic", "Apple SD Gothic Neo", "Segoe UI Emoji", sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=s.color;if(s.shadow){ctx.shadowColor='#00000070';ctx.shadowBlur=8;ctx.shadowOffsetY=3}const lines=wrap(ctx,s.text,w*.86),lh=s.size*1.4,x=w*s.x/100,y=h*s.y/100-(lines.length-1)*lh/2;let overflow=false;lines.forEach((line,i)=>{const width=ctx.measureText(line).width,py=y+i*lh;if(line&&(x-width/2<10||x+width/2>w-10||py-s.size*.7<0||py+s.size*.7>h))overflow=true;ctx.fillText(line,x,py)});return overflow}
function render(){const overflow=draw();$('overflow').hidden=!overflow;$('dimensions').textContent=sizes[state.ratio].join(' × ')+' px';for(const key of ['size','x','y'])$(key+'-value').textContent=state[key]+(key==='size'?'px':'%');$('color-value').textContent=state.color.toUpperCase();document.querySelectorAll('[data-ratio]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ratio===state.ratio)));$('remove-image').hidden=!state.image;$('image-name').textContent=state.image?'이미지가 적용됐어요. 중앙을 기준으로 비율에 맞춰 잘립니다.':'사진 없이 기본 배경으로 시작해도 좋아요.'}
function sync(){for(const k of ['text','size','color','x','y'])$(k).value=state[k];$('shadow').checked=state.shadow;render()}
function decode(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('이미지 데이터를 읽을 수 없습니다. 기존 작업은 유지됩니다.'));img.src=src})}
function readData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('파일을 읽지 못했습니다.'));r.readAsDataURL(file)})}
async function cleanImage(file){if(file.size>10*1024*1024)throw Error('이미지는 10MB 이하만 사용할 수 있습니다.');const bytes=new Uint8Array(await file.slice(0,12).arrayBuffer());const png=[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v),jpeg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;if(!png&&!jpeg)throw Error('PNG 또는 JPEG 이미지 파일만 사용할 수 있습니다.');const img=await decode(await readData(file));if(img.width*img.height>20000000)throw Error('2,000만 픽셀 이하 이미지를 사용하세요.');const scale=Math.min(1,2560/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/png')}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('jjal-card-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function readSaved(){return new Promise((resolve,reject)=>{const r=db.transaction('data').objectStore('data').get('templates');r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
function persist(next){return new Promise((resolve,reject)=>{if(!db)return reject(Error('브라우저 저장소를 사용할 수 없습니다.'));const tx=db.transaction('data','readwrite');tx.objectStore('data').put(next,'templates');tx.oncomplete=resolve;tx.onerror=()=>reject(Error('저장 공간이 부족하거나 저장에 실패했습니다. 기존 템플릿은 유지됩니다.'));tx.onabort=()=>reject(Error('저장하지 못했습니다. 기존 템플릿은 유지됩니다.'))})}
async function transaction(action){if(busy)return;busy=true;document.querySelectorAll('#save,#update,#import,#export,.template-card button').forEach(b=>b.disabled=true);try{await action()}catch(e){message(e.message,true)}finally{busy=false;document.querySelectorAll('#save,#update,#import,#export,.template-card button').forEach(b=>b.disabled=false)}}
function thumbnail(){const c=document.createElement('canvas');c.width=160;c.height=160;const src=$('canvas'),r=Math.min(160/src.width,160/src.height);c.getContext('2d').drawImage(src,(160-src.width*r)/2,(160-src.height*r)/2,src.width*r,src.height*r);return c.toDataURL('image/png')}
function list(){const root=$('template-list');root.replaceChildren();$('count').textContent=templates.length;$('update').hidden=!selected;if(!templates.length){const p=document.createElement('p');p.className='empty';p.textContent='마음에 드는 조합을 저장해 두세요.';root.append(p)}for(const t of templates){const card=document.createElement('article');card.className='template-card'+(selected===t.id?' selected':'');const img=document.createElement('img');img.src=t.thumbnail;img.alt=t.name+' 미리보기';const body=document.createElement('div'),title=document.createElement('strong');title.textContent=t.name;body.append(title);for(const [label,action,cls] of [['불러오기',()=>load(t.id),''],['삭제',()=>remove(t.id),'delete']]){const b=document.createElement('button');b.textContent=label;b.className=cls;b.onclick=action;body.append(b)}card.append(img,body);root.append(card)}}
async function save(update=false){await transaction(async()=>{const name=$('template-name').value.trim();if(!name)throw Error('템플릿 이름을 입력하세요.');if(!update&&templates.length>=30)throw Error('템플릿은 최대 30개까지 저장할 수 있습니다.');if(update&&!templates.some(t=>t.id===selected))throw Error('수정할 템플릿을 먼저 불러오세요.');const item={id:update?selected:crypto.randomUUID(),name,state:clone(state),thumbnail:thumbnail()};const next=update?templates.map(t=>t.id===selected?item:t):[...templates,item];await persist(next);templates=next;selected=item.id;list();message(update?'선택한 템플릿을 수정했어요.':'템플릿을 저장했어요. 새로고침해도 유지됩니다.')})}
async function load(id){await transaction(async()=>{const t=templates.find(t=>t.id===id);if(!t)throw Error('템플릿을 찾을 수 없습니다.');const img=t.state.image?await decode(t.state.image):null;++uploadTicket;picture=img;state=clone(t.state);selected=id;$('template-name').value=t.name;sync();list();message('템플릿을 불러왔어요. 편집 후 수정 저장할 수 있습니다.')})}
async function remove(id){if(!confirm('이 템플릿을 삭제할까요? 현재 편집 중인 카드는 유지됩니다.'))return;await transaction(async()=>{const next=templates.filter(t=>t.id!==id);await persist(next);templates=next;if(selected===id){selected=null;$('template-name').value=''}list();message('템플릿을 삭제했어요.')})}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function validateState(s){if(!s||typeof s!=='object'||!Object.hasOwn(sizes,s.ratio)||typeof s.text!=='string'||s.text.length>2000||!/^#[0-9a-f]{6}$/i.test(s.color)||typeof s.shadow!=='boolean'||!Object.hasOwn(palettes,s.bg)||!(s.image===null||(typeof s.image==='string'&&/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(s.image)&&s.image.length<30000000)))throw Error('JSON의 필수 항목 또는 이미지 형식이 올바르지 않습니다.');for(const [key,min,max] of [['size',24,160],['x',0,100],['y',0,100]])if(typeof s[key]!=='number'||!Number.isFinite(s[key])||s[key]<min||s[key]>max)throw Error('JSON의 글자 크기 또는 위치 범위가 올바르지 않습니다.');return {ratio:s.ratio,text:s.text,size:s.size,color:s.color,x:s.x,y:s.y,shadow:s.shadow,bg:s.bg,image:s.image}}
async function importJSON(text){if(text.length>50*1024*1024)throw Error('JSON은 50MB 이하만 가져올 수 있습니다.');let data;try{data=JSON.parse(text)}catch{throw Error('JSON 문법이 손상되었습니다. 기존 템플릿은 유지됩니다.')}if(!data||data.version!==1||!Array.isArray(data.templates)||!data.templates.length||data.templates.length>30)throw Error('버전 또는 템플릿 목록이 올바르지 않습니다.');if(data.templates.length+templates.length>30)throw Error('가져온 뒤 템플릿 수가 30개를 넘습니다.');const imported=[];for(const item of data.templates){if(typeof item.name!=='string'||!item.name.trim()||item.name.length>60)throw Error('템플릿 이름이 없거나 올바르지 않습니다.');const s=validateState(item.state);let img=null;if(s.image){img=await decode(s.image);if(img.width*img.height>20000000)throw Error('JSON 이미지가 너무 큽니다.');const clean=document.createElement('canvas');clean.width=img.width;clean.height=img.height;clean.getContext('2d').drawImage(img,0,0);s.image=clean.toDataURL('image/png')}const c=document.createElement('canvas');draw(c,s,img);const thumb=document.createElement('canvas');thumb.width=160;thumb.height=160;const r=Math.min(160/c.width,160/c.height);thumb.getContext('2d').drawImage(c,(160-c.width*r)/2,(160-c.height*r)/2,c.width*r,c.height*r);imported.push({id:crypto.randomUUID(),name:item.name.trim(),state:s,thumbnail:thumb.toDataURL('image/png')})}const next=[...templates,...imported];await persist(next);templates=next;list();message(`${imported.length}개 템플릿을 추가했어요. 기존 목록은 유지됩니다.`)}
for(const key of ['text','size','color','x','y'])$(key).addEventListener('input',()=>{state[key]=['size','x','y'].includes(key)?Number($(key).value):$(key).value;render()});$('shadow').onchange=()=>{state.shadow=$('shadow').checked;render()};document.querySelectorAll('[data-ratio]').forEach(b=>b.onclick=()=>{state.ratio=b.dataset.ratio;render()});document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>{++uploadTicket;state.bg=b.dataset.bg;state.image=null;picture=null;render()});$('remove-image').onclick=()=>{++uploadTicket;state.image=null;picture=null;render()};
$('image-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;const ticket=++uploadTicket;try{message('이미지를 읽고 있어요…');const data=await cleanImage(file),img=await decode(data);if(ticket!==uploadTicket)return;state.image=data;picture=img;render();message('이미지를 불러왔어요. 원본 메타데이터는 저장하지 않습니다.')}catch(error){if(ticket===uploadTicket)message(error.message+' 기존 편집 내용은 유지됩니다.',true)}};
$('save').onclick=()=>save();$('update').onclick=()=>save(true);$('download').onclick=async()=>{await document.fonts.ready;render();$('canvas').toBlob(blob=>{if(blob){downloadBlob(blob,`jjal-card-${state.ratio.replace(':','x')}.png`);message('PNG를 다운로드했어요.')}else message('이미지 저장에 실패했습니다.',true)},'image/png')};$('export').onclick=()=>{if(!templates.length)return message('먼저 템플릿을 하나 이상 저장하세요.',true);downloadBlob(new Blob([JSON.stringify({version:1,templates:templates.map(({id,name,state})=>({id,name,state}))},null,2)],{type:'application/json'}),'jjal-templates.json');message('이미지가 포함된 템플릿 JSON을 내보냈어요.')};$('import').onclick=()=>$('json-file').click();$('json-file').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)transaction(async()=>{if(file.size>50*1024*1024)throw Error('JSON은 50MB 이하만 가져올 수 있습니다.');await importJSON(await file.text())})};
sync();document.fonts.ready.then(render);openDB().then(async d=>{db=d;templates=await readSaved();list()}).catch(()=>message('브라우저 저장소를 열 수 없습니다. 이미지 편집과 다운로드는 가능합니다.',true));
// A stage: basic movement. Boundary clamping and pointer lifecycle hardening
// are the planned B stage, described in the handoff.
let textDrag=null;
$('canvas').addEventListener('pointerdown',event=>{
 if(event.button!==0||!state.text)return;
 const canvas=$('canvas'),box=canvas.getBoundingClientRect(),ctx=canvas.getContext('2d');
 const px=(event.clientX-box.left)*canvas.width/box.width;
 const py=(event.clientY-box.top)*canvas.height/box.height;
 const lines=wrap(ctx,state.text,canvas.width*.86);
 const width=Math.max(...lines.map(line=>ctx.measureText(line).width));
 const cx=canvas.width*state.x/100,cy=canvas.height*state.y/100;
 if(Math.abs(px-cx)>width/2+20||Math.abs(py-cy)>lines.length*state.size*.7+20)return;
 textDrag={clientX:event.clientX,clientY:event.clientY,x:state.x,y:state.y,width:box.width,height:box.height};
 event.preventDefault();
});
document.addEventListener('pointermove',event=>{
 if(!textDrag)return;
 state.x=textDrag.x+(event.clientX-textDrag.clientX)/textDrag.width*100;
 state.y=textDrag.y+(event.clientY-textDrag.clientY)/textDrag.height*100;
 sync();
});
document.addEventListener('pointerup',()=>{textDrag=null});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_card',title:'카드 문구 편집',description:'현재 카드의 문구를 바꾸고 미리보기를 갱신합니다. 저장하거나 다운로드하지 않습니다.',inputSchema:{type:'object',properties:{text:{type:'string',maxLength:2000}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.text!=='string'||input.text.length>2000)throw Error('문구는 2000자 이하여야 합니다.');state.text=input.text;sync();return {text:state.text,ratio:state.ratio}}})).catch(()=>{})}catch{}}
